import json
from pathlib import Path

# ১) সংরক্ষিত Design Lab এবং MovieLens Capstone Artifact লোড করি (কোনো numpy/pandas ছাড়াই!)
lab = json.loads(
    Path("assets/datasets/system_design/design_lab.json").read_text(encoding="utf-8")
)
ml = json.loads(
    Path("assets/datasets/movielens/recommender_capstone_lab.json").read_text(encoding="utf-8")
)

# ২) User 15-এর ৩টি Fit-only উৎস থেকে নিজেই Weighted RRF পুনঃগণনা করি
user15 = None
for r in ml["roles"]["audit"]:
    if r["user"] == 15:
        user15 = r
        break

weights = {"popularity": 1.0, "content": 1.0, "user_cf": 2.0}
scores = {}
for src_name in ["popularity", "content", "user_cf"]:
    items = user15["sources"][src_name][:50]
    for idx in range(len(items)):
        item_id = items[idx]
        rank = idx + 1
        scores[item_id] = scores.get(item_id, 0.0) + weights[src_name] / (60.0 + rank)

def rrf_sort_key(item_id):
    return (-round(scores[item_id], 12), item_id)

ranked_top10 = sorted(scores.keys(), key=rrf_sort_key)[:10]
fallback_top10 = user15["sources"]["popularity"][:10]

# ৩) design_lab.json-এর স্বাভাবিক ও বিপর্যস্ত Response-এর সাথে মিলিয়ে দেখি
normal = lab["responses"]["recommendation"]["none"]
degraded = lab["responses"]["recommendation"]["upstream"]
assert ranked_top10 == normal["output"]["items"]
assert fallback_top10 == degraded["output"]["items"]

print("Normal   (weighted_rrf)  :", normal["status"], ranked_top10)
print("Degraded (fit_popularity):", degraded["status"], fallback_top10)
overlap = 0
for x in ranked_top10:
    if x in fallback_top10:
        overlap += 1
print(f"Overlap between personalized Top-10 and popularity Fallback: {overlap}/10")

import json
from pathlib import Path

# ১) সংরক্ষিত Design Lab থেকে Search Case-এর স্বাভাবিক ও Fallback আচরণ লোড করি
lab = json.loads(
    Path("assets/datasets/system_design/design_lab.json").read_text(encoding="utf-8")
)

normal = lab["responses"]["search"]["none"]
fallback = lab["responses"]["search"]["upstream"]
blocked = lab["responses"]["search"]["model_mismatch"]

print("Normal   :", normal["status"], "|", normal["served"], "| docs:", normal["output"]["documents"])
print("Fallback :", fallback["status"], "|", fallback["served"], "| docs:", fallback["output"]["documents"])
print("Mismatch :", blocked["status"], "|", blocked["reason"])

# ২) হাতে-কলমে ছোট Hybrid RRF বনাম Lexical-only Fallback লজিক যাচাই (কোনো numpy/pandas ছাড়াই!)
lex_ranked = ["doc_42", "doc_17", "doc_88", "doc_05"]
lsa_ranked = ["doc_88", "doc_99", "doc_42", "doc_12"]

def run_search_service(lex_list, lsa_list, dense_healthy, allowed_docs, top_k=3):
    if not lex_list:
        return {"status": "ABSTAIN", "served": "none", "docs": []}
    if not dense_healthy:
        filtered = []
        for d in lex_list:
            if d in allowed_docs:
                filtered.append(d)
        return {"status": "DEGRADED", "served": "lexical_tfidf", "docs": filtered[:top_k]}
    scores = {}
    for branch in [lex_list, lsa_list]:
        for idx in range(len(branch)):
            doc_id = branch[idx]
            if doc_id in allowed_docs:
                scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (61.0 + idx)
    def sort_key(doc_id):
        return (-round(scores[doc_id], 12), doc_id)
    ranked = sorted(scores.keys(), key=sort_key)
    return {"status": "OK", "served": "hybrid_rrf", "docs": ranked[:top_k]}

# ধরুন doc_17 গোপন (Unauthorized) নথি!
acl_allowed = {"doc_42", "doc_88", "doc_99", "doc_05", "doc_12"}
print("Simulated Hybrid (ACL enforced)  :", run_search_service(lex_ranked, lsa_ranked, True, acl_allowed))
print("Simulated Fallback (LSA down)    :", run_search_service(lex_ranked, lsa_ranked, False, acl_allowed))

import json
import math
from pathlib import Path

# ১) Spambase ৭৩৮টি Dev-Validation Row লোড করি (কোনো numpy বা pandas ছাড়াই!)
lab = json.loads(
    Path("assets/datasets/system_design/design_lab.json").read_text(encoding="utf-8")
)
rows = lab["spam"]["validation"]

def run_selective_policy(data_rows, low=0.2, high=0.8, budget=50, overflow="defer", fp_cost=100):
    routes = []
    uncertain_idx = []
    for j in range(len(data_rows)):
        p = data_rows[j]["score"]
        if p < low:
            routes.append("allow")
        elif p >= high:
            routes.append("block")
        else:
            routes.append("pending")
            uncertain_idx.append(j)

    def priority_key(j):
        dist = math.floor(abs(data_rows[j]["score"] - 0.5) * 1e12 + 0.5)
        return (dist, data_rows[j]["index"])

    uncertain_idx.sort(key=priority_key)
    for k in range(len(uncertain_idx)):
        j = uncertain_idx[k]
        if k < budget:
            routes[j] = "review"
        else:
            routes[j] = overflow

    allow = block = review = defer = fp = fn = 0
    for j in range(len(data_rows)):
        rt = routes[j]
        y = data_rows[j]["label"]
        if rt == "allow":
            allow += 1
            if y == 1:
                fn += 1
        elif rt == "block":
            block += 1
            if y == 0:
                fp += 1
        elif rt == "review":
            review += 1
        else:
            defer += 1

    decided = allow + block
    pending = review + defer
    cov = decided / len(data_rows)
    cond_acc = (decided - fp - fn) / decided if decided > 0 else 0.0
    cost = fp_cost * fp + fn
    return {
        "decided": decided, "review": review, "defer": defer, "pending": pending,
        "coverage": cov, "fp": fp, "fn": fn, "cond_acc": cond_acc, "cost": cost,
    }

# ২) তিনটি Overflow নীতি ('defer', 'allow', 'block') হাতে-কলমে তুলনা করি
default_res = run_selective_policy(rows, overflow="defer")
assert default_res["decided"] == 606 and default_res["review"] == 50 and default_res["defer"] == 82
assert default_res["fp"] == 10 and default_res["fn"] == 8 and default_res["cost"] == 1008

for mode in ["defer", "allow", "block"]:
    r = run_selective_policy(rows, overflow=mode)
    print(
        f"overflow={mode:5s} | decided={r['decided']:3d} ({r['coverage']:.3f}) | "
        f"FP={r['fp']:2d} | FN={r['fn']:2d} | cond_acc={r['cond_acc']:.4f} | proxy_cost={r['cost']}"
    )

import json
from pathlib import Path

# ১) Frozen Bike Sharing Serving Lab এবং Design Lab লোড করি (কোনো numpy/pandas ছাড়াই!)
lab = json.loads(
    Path("assets/datasets/system_design/design_lab.json").read_text(encoding="utf-8")
)
bike = json.loads(
    Path("assets/datasets/bike_sharing/serving_lab.json").read_text(encoding="utf-8")
)

model = bike["models"]["candidate"]

def serve_bike_forecast(events, target_day, cutoff_day):
    # কঠোর দুই ঘড়ি: event_day < target_day AND available_day <= cutoff_day
    known = {}
    for row in events:
        if row["event_day"] < target_day and row["available_day"] <= cutoff_day:
            known[row["event_day"]] = row["cnt"]

    lag1 = known.get(target_day - 1)
    lag7 = known.get(target_day - 7)

    # ৭ দিনের উইন্ডোর গড় (কেবল লভ্য দিনগুলোর ওপর!)
    win_sum = 0.0
    win_cnt = 0
    for d in range(target_day - 7, target_day):
        if d in known:
            win_sum += known[d]
            win_cnt += 1

    if lag1 is not None and lag7 is not None and win_cnt > 0:
        feats = {"lag1": lag1, "lag7": lag7, "mean7": win_sum / win_cnt}
        pred = model["intercept"]
        for idx in range(len(model["input_fields"])):
            fname = model["input_fields"][idx]
            z = (feats[fname] - model["mean"][idx]) / model["scale"][idx]
            pred += model["weights"][idx] * z
        if pred < 0.0:
            pred = 0.0
        return {"status": "OK", "served": "ridge", "prediction": pred}

    if lag7 is not None:
        return {"status": "DEGRADED", "served": "seasonal7", "prediction": float(lag7)}

    return {"status": "ABSTAIN", "served": "none", "prediction": None}

# ২) on_time, late_fixture এবং সব ডেটা অনুপস্থিত—তিনটি অবস্থাই যাচাই করি
r_ok = serve_bike_forecast(bike["events"]["on_time"], 375, 375)
r_late = serve_bike_forecast(bike["events"]["late_fixture"], 375, 375)
r_empty = serve_bike_forecast([], 375, 375)

assert abs(r_ok["prediction"] - lab["responses"]["forecast"]["none"]["output"]["prediction"]) < 1e-9
assert r_late["served"] == "seasonal7" and r_late["prediction"] == 2368.0

print("On-time   :", r_ok["status"], "|", r_ok["served"], "| pred =", round(r_ok["prediction"], 2))
print("Late data :", r_late["status"], "|", r_late["served"], "| pred =", r_late["prediction"])
print("No data   :", r_empty["status"], "|", r_empty["served"], "| pred =", r_empty["prediction"])

### Pure Python কোডের যাচাই করা Output
- `Total rows (N)           : 738`
- `Automatic decided (auto) : 606 (Coverage = 0.8211)`
- `Unresolved pending       : 132 (review=50 + defer=82)`
- `Conditional auto accuracy: 0.970297 (588/606)`
- `Overall accuracy bounds  : [0.796748, 0.975610] (denom=738)`

### তিনটি গুরুত্বপূর্ণ Production Monitoring শৃঙ্খলা
1. **Drift Alert $\neq$ অন্ধ Auto-Retrain:** Drift Score বাড়লে সঙ্গে সঙ্গে চোখ বন্ধ করে Model Retrain করা ভয়াবহ ঝুঁকিপূর্ণ! Drift-এর কারণ হতে পারে আপস্ট্রিম Schema বাগ, স্প্যামার ক্যাম্পেইন বা মৌসুমি উৎসব—বাগি ডেটায় Retrain করলে Model পুরোপুরি নষ্ট হয়ে যাবে! আগে Root Cause তদন্ত করুন।
2. **Bounded Metric Cardinality ও Privacy Hygiene:** `user_id` বা `request_id`-এর মতো লক্ষ লক্ষ অনন্য মান (High-cardinality) কখনোই Prometheus/Time-series Metric Tag-এ বসাবেন না—এতে Monitoring Database মুহূর্তেই ধসে পড়বে! এগুলো রাখুন Sampled Trace বা Structured Log-এ, আর কাঁচা PII/ব্যক্তিগত ইমেইল/Prompt কখনোই সাধারণ লগে লিখবেন না।
3. **ইন্টারভিউ প্লেবুক (`HTTP 200` ঠিক আছে, কিন্তু Fallback বেড়ে গেছে!):** (ক) ইচ্ছাকৃত Policy পরিবর্তন বনাম নীরব ব্যর্থতা আলাদা করা, (খ) `version` ও `reason` কোড (`upstream_timeout`, `missing_lag1`) দিয়ে Slice করা, (গ) `OK`/`DEGRADED`/`DEFER`/`ABSTAIN` অনুপাত আগের ঘণ্টার সাথে মেলানো। মনে রাখুন: **`HTTP 200` সফল হওয়া মানেই উত্তরটি ব্যক্তিগতকৃত বা উপকারী নয়!**

### Option B — Pure Python-এ Bounded-Cardinality Metric Tag ও Signal Validator
Time-series ড্যাশবোর্ডে High-cardinality বা PII Tag ঢোকা ঠেকাতে Ingestion গেটে নিচের মতো Guard চালানো হয়:

```python
ALLOWED_METRIC_TAGS = {"case", "status", "served", "reason", "model_ver", "policy_id"}
FORBIDDEN_PII_OR_HIGH_CARD = {"user_id", "request_id", "email", "raw_query", "ip_address"}

def emit_metric(metric_name, value, unit, denom, window, tags):
    rejected = []
    for k in tags:
        if k in FORBIDDEN_PII_OR_HIGH_CARD or k not in ALLOWED_METRIC_TAGS:
            rejected.append(k)
    if rejected:
        return {"emitted": False, "error": "disallowed_tags:" + ",".join(sorted(rejected))}
    if denom <= 0:
        return {"emitted": False, "error": "invalid_denominator"}
    return {
        "emitted": True,
        "signal": (metric_name, value, unit, f"denom={denom}", window, tags["model_ver"]),
    }

good = emit_metric("fallback_rate", 0.12, "ratio", 5000, "5m", {"case": "search", "status": "DEGRADED", "model_ver": "v2"})
bad = emit_metric("fallback_rate", 0.12, "ratio", 5000, "5m", {"case": "search", "user_id": "u_99182", "model_ver": "v2"})
print("Valid metric:", good)
print("Guarded bad :", bad)
```

**Python যাচাই করা Output:**
- `Valid metric: {'emitted': True, 'signal': ('fallback_rate', 0.12, 'ratio', 'denom=5000', '5m', 'v2')}`
- `Guarded bad : {'emitted': False, 'error': 'disallowed_tags:user_id'}`

